plugins {
	base
	`maven-publish`
	id("com.google.devtools.ksp") version "2.3.9" apply false
	kotlin("jvm") version "2.3.21" apply false
	id("com.gradleup.shadow") version "9.4.2" apply false
	id("io.papermc.paperweight.userdev") version "2.0.0-SNAPSHOT" apply false
}

val qpluginVersion = "1.14.5.5.1"

allprojects {
	group = "vip.qoriginal"
	version = qpluginVersion
	description = "QuantumPlugin"

	repositories {
		mavenLocal()
		maven {
			url = uri("https://repo.maven.apache.org/maven2/")
		}
		maven {
			url = uri("https://repo.papermc.io/repository/maven-public/")
		}
		maven {
			url = uri("https://oss.sonatype.org/content/groups/public/")
		}
		mavenCentral()
	}
}

val hotModules = listOf("sponsor-prefix", "daily-login", "combat-feedback", "text-displays", "seasonal-events")
val javaProjects = (listOf("common", "survival", "creative", "chambers", "hot-api", "hot-runtime", "test-support:paper-probe") + hotModules.map { "modules:$it" }).map { project(":$it") }
val gsonDependency = libs.com.google.code.gson.gson
val kotlinStdlibDependency = libs.org.jetbrains.kotlin.kotlin.stdlib
val kotlinReflectDependency = libs.org.jetbrains.kotlin.kotlin.reflect
val coroutinesDependency = libs.org.jetbrains.kotlinx.kotlinx.coroutines.core
val paperApiDependency = libs.io.papermc.paper.paper.api

configure(javaProjects) {
	apply(plugin = "java-library")
	apply(plugin = "org.jetbrains.kotlin.jvm")
	apply(plugin = "maven-publish")

	dependencies {
		"implementation"(gsonDependency)
		"api"(kotlinStdlibDependency)
		"api"(kotlinReflectDependency)
		"api"(coroutinesDependency)
		"compileOnly"(paperApiDependency)
		"implementation"(kotlin("stdlib-jdk8"))
	}

	tasks.withType<JavaCompile>().configureEach {
		options.encoding = "UTF-8"
	}

	tasks.withType<Javadoc>().configureEach {
		options.encoding = "UTF-8"
	}

	extensions.configure<org.jetbrains.kotlin.gradle.dsl.KotlinJvmProjectExtension>("kotlin") {
		jvmToolchain(25)
		sourceSets.named("main") {
			kotlin.setSrcDirs(listOf("src/main/java"))
		}
	}

	tasks.withType<org.gradle.jvm.tasks.Jar>().configureEach {
		isPreserveFileTimestamps = false
		isReproducibleFileOrder = true
		from(listOf(rootProject.file("LICENSE"), rootProject.file("COPYING"))) {
			into("META-INF/licenses/${project.name}")
		}
	}

	publishing {
		publications.create<MavenPublication>("maven") {
			from(components["java"])
			pom {
				licenses {
					license {
						name.set("GNU Lesser General Public License v3.0 only")
						url.set("https://www.gnu.org/licenses/lgpl-3.0.html")
						distribution.set("repo")
					}
				}
			}
		}
	}
}

val pluginProjects = mapOf(
	"survival" to "QuantumPlugin",
	"creative" to "QuantumPlugin-Creative",
	"chambers" to "QuantumPlugin-Chambers",
)

pluginProjects.forEach { (projectName, archiveName) ->
	project(":$projectName") {
		apply(plugin = "com.gradleup.shadow")

		dependencies {
		"implementation"(project(":common"))
		"implementation"(kotlin("compiler-embeddable"))
		"implementation"("com.google.devtools.ksp:symbol-processing-api:2.3.9")
	}

		tasks.named<com.github.jengelman.gradle.plugins.shadow.tasks.ShadowJar>("shadowJar") {
			archiveBaseName.set(archiveName)
			archiveClassifier.set("")
			mergeServiceFiles()
			dependencies {
				exclude(dependency("com.google.devtools.ksp:.*"))
				exclude(dependency("org.jetbrains.kotlin:kotlin-compiler-embeddable.*"))
			}
		}

		tasks.named("build") {
			dependsOn("shadowJar")
		}
	}
}

project(":chambers") {
	dependencies {
		"testImplementation"(kotlin("test"))
	}
}

project(":survival") {
	apply(plugin = "com.google.devtools.ksp")
	apply(plugin = "io.papermc.paperweight.userdev")

	extensions.configure<org.jetbrains.kotlin.gradle.dsl.KotlinJvmProjectExtension>("kotlin") {
		jvmToolchain(25)
	}

	val survivalJavaToolchains = extensions.getByType<org.gradle.jvm.toolchain.JavaToolchainService>()
	extensions.configure<io.papermc.paperweight.userdev.PaperweightUserExtension>("paperweight") {
		javaLauncher.set(survivalJavaToolchains.launcherFor {
			languageVersion.set(JavaLanguageVersion.of(25))
		})
	}

	dependencies {
		"ksp"(project(":processor"))
		"implementation"("io.github.classgraph:classgraph:4.8.181")
		"testImplementation"(kotlin("test"))
		"paperweightDevelopmentBundle"("io.papermc.paper:dev-bundle:26.2.build.+")
	}
}

project(":common") {
	apply(plugin = "io.papermc.paperweight.userdev")

	val commonJavaToolchains = extensions.getByType<org.gradle.jvm.toolchain.JavaToolchainService>()
	extensions.configure<io.papermc.paperweight.userdev.PaperweightUserExtension>("paperweight") {
		javaLauncher.set(commonJavaToolchains.launcherFor {
			languageVersion.set(JavaLanguageVersion.of(25))
		})
	}

	dependencies {
		"implementation"(project(":hot-runtime"))
		"paperweightDevelopmentBundle"("io.papermc.paper:dev-bundle:26.2.build.+")
		"testImplementation"(kotlin("test"))
	}
}

project(":hot-runtime") {
	dependencies {
		"api"(project(":hot-api"))
		"testImplementation"(kotlin("test"))
		"testImplementation"(paperApiDependency)
	}
}

val hotReleaseId = providers.gradleProperty("releaseId").orElse("development")
configure(hotModules.map { project(":modules:$it") }) {
	dependencies {
		"compileOnly"(project(":hot-api"))
		"testImplementation"(kotlin("test"))
		"testImplementation"(project(":hot-api"))
		"testImplementation"(paperApiDependency)
	}
	tasks.withType<ProcessResources>().configureEach {
		val moduleVersion = hotReleaseId.get()
		inputs.property("releaseId", moduleVersion)
		filesMatching("META-INF/qplugin-module.properties") {
			expand("moduleVersion" to moduleVersion, "apiVersion" to 2)
		}
	}
}

val hotModuleIndexOutput = layout.buildDirectory.file("generated/hot-modules/modules.properties")
val writeHotModuleIndex = tasks.register<WriteProperties>("writeHotModuleIndex") {
	destinationFile.set(hotModuleIndexOutput)
	property("modules", hotModules.joinToString(","))
}

project(":common").tasks.named<ProcessResources>("processResources") {
	dependsOn(writeHotModuleIndex)
	from(hotModuleIndexOutput) { into("hot-modules") }
	hotModules.forEach { module ->
		dependsOn(":modules:$module:jar")
		from(project(":modules:$module").tasks.named("jar")) {
			into("hot-modules")
			rename { "$module.jar" }
		}
	}
}

val hotReleaseRuntime = configurations.create("hotReleaseRuntime") {
	isCanBeConsumed = false
	isCanBeResolved = true
}
dependencies { add(hotReleaseRuntime.name, project(":hot-runtime")) }

tasks.register<JavaExec>("packageHotRelease") {
	group = "distribution"
	description = "Build immutable plugin/module release and SHA-256 manifest (-PreleaseId=<commit>)."
	dependsOn(":hot-runtime:classes", ":survival:shadowJar", ":creative:shadowJar", ":chambers:shadowJar")
	dependsOn(hotModules.map { ":modules:$it:jar" })
	classpath = hotReleaseRuntime
	mainClass.set("vip.qoriginal.quantumplugin.hot.runtime.ReleasePackager")
	javaLauncher.set(project(":hot-runtime").extensions.getByType<JavaToolchainService>().launcherFor {
		languageVersion.set(JavaLanguageVersion.of(25))
	})
	args(hotReleaseId.get(), layout.buildDirectory.dir("releases").get().asFile.absolutePath)
	hotModules.forEach { module ->
		args("--module", project(":modules:$module").layout.buildDirectory.file("libs/$module-$qpluginVersion.jar").get().asFile.absolutePath)
	}
	pluginProjects.forEach { (target, name) ->
		args("--host", name, project(":$target").layout.buildDirectory.file("libs/$name-$qpluginVersion.jar").get().asFile.absolutePath)
	}
}

tasks.named("build") {
	dependsOn(":survival:shadowJar", ":creative:shadowJar", ":chambers:shadowJar", ":hot-runtime:build")
	dependsOn(hotModules.map { ":modules:$it:build" })
}
